// import { API_BASE_URL } from './config.js';
const API_BASE_URL = 'http://140.127.220.85:3001';//待修改

document.addEventListener("DOMContentLoaded", function () {
  const form = document.getElementById("register-form");
  const inputs = form.querySelectorAll("input");
  const [usernameInput, emailInput, passwordInput, password2Input, phoneInput] = inputs;
  const verifyCodeGroup = document.getElementById("verify-code-group");
  const verifyCodeInput = document.getElementById("verify-code-input");
  const registerBtn = document.getElementById("register-btn");
  const verifyBtn = document.getElementById("verify-btn");

  let tempEmail = "";

  // 建立錯誤訊息元素
  function createErrorEl(input) {
    let el = input.nextElementSibling;
    if (!el || !el.classList.contains('input-error')) {
      el = document.createElement('div');
      el.className = 'input-error text-danger small mt-1';
      input.parentNode.appendChild(el);
    }
    return el;
  }

  // 即時驗證
  usernameInput.addEventListener('input', function () {
    const el = createErrorEl(this);
    el.textContent = this.value.trim() ? '' : '請輸入會員名稱';
  });
  emailInput.addEventListener('input', function () {
    const el = createErrorEl(this);
    el.textContent = this.value.trim() ? '' : '請輸入電子郵件';
  });
  passwordInput.addEventListener('input', function () {
    const el = createErrorEl(this);
    el.textContent = this.value ? '' : '請輸入密碼';
  });
  password2Input.addEventListener('input', function () {
    const el = createErrorEl(this);
    if (!this.value) {
      el.textContent = '請再次輸入密碼';
    } else if (this.value !== passwordInput.value) {
      el.textContent = '兩次密碼輸入不一致';
    } else {
      el.textContent = '';
    }
  });
  phoneInput.addEventListener('input', function () {
    const el = createErrorEl(this);
    el.textContent = this.value.trim() ? '' : '請輸入手機號碼';
  });

  // 註冊
  form.addEventListener("submit", function (e) {
    e.preventDefault();

    // 基本驗證
    const username = usernameInput.value.trim();
    const email = emailInput.value.trim();
    const password = passwordInput.value;
    const password2 = password2Input.value;
    const phone = phoneInput.value.trim();

    if (!username || !email || !password || !password2 || !phone) {
      alert("請填寫所有欄位");
      return;
    }
    if (password !== password2) {
      alert("兩次密碼輸入不一致");
      return;
    }

    registerBtn.disabled = true;
    registerBtn.textContent = "寄送驗證信中...";

    fetch(`${API_BASE_URL}/api//register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        username,
        email,
        password,
        phone
      })
    })
      .then(res => res.json())
      .then(data => {
        if (data.ok) {
          alert(data.message || "驗證信已寄出，請至信箱收取驗證碼！");
          tempEmail = email;
          verifyCodeGroup.classList.remove("d-none");
          verifyBtn.classList.remove("d-none");
          registerBtn.classList.add("d-none");
          [usernameInput, emailInput, passwordInput, password2Input, phoneInput].forEach(i => i.disabled = true);
        } else {
          alert(data.message || data.error || "註冊失敗，請重試");
          registerBtn.disabled = false;
          registerBtn.textContent = "🚀 註冊";
        }
      })
      .catch(() => {
        alert("伺服器錯誤，請稍後再試");
        registerBtn.disabled = false;
        registerBtn.textContent = "🚀 註冊";
      });
  });

  // 驗證碼
  verifyBtn.addEventListener("click", function () {
    const code = verifyCodeInput.value.trim();
    if (!code) {
      alert("請輸入驗證碼");
      return;
    }
    verifyBtn.disabled = true;
    verifyBtn.textContent = "驗證中...";

    fetch(`${API_BASE_URL}/api//verify`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: tempEmail,
        code
      })
    })
      .then(res => res.json())
      .then(data => {
        if (data.ok) {
          alert(data.message || "驗證成功，請登入！");
          window.location.href = "/login";
        } else {
          alert(data.message || data.error || "驗證失敗，請重試");
          verifyBtn.disabled = false;
          verifyBtn.textContent = "送出驗證碼";
        }
      })
      .catch(() => {
        alert("伺服器錯誤，請稍後再試");
        verifyBtn.disabled = false;
        verifyBtn.textContent = "送出驗證碼";
      });
  });
});
